// ─── NORMALIZE : Uses pre-extracted fields from search-apis ───

// PORTEE DE CE NOEUD (mesure du 2026-09-28 : graphe des appels des workflows, puis recherche
// des chemins de webhook dans src, app/src, monitor/src et scripts). Il n'est appele que par
// l'orchestrateur `ultralab-review` (ultralab-systematicreview-orchestrator.json), dont le
// webhook n'a aucun appelant : l'ancienne interface qui l'appelait est retiree depuis le
// 2026-09-10 (decision de l'auteur, docs/RECETTE-0.5.2.md). Les recherches de l'application
// passent par le webhook `ultralab-api-search`, dont le workflow n'appelle que
// ultralab-search-apis.json : elles ne traversent pas ce noeud. Ses corrections valent pour cet
// orchestrateur et pour les corpus qu'il a ecrits, pas pour les dossiers que l'application
// produit aujourd'hui.

function __ulNormDoi(v) {
  // LA REGLE CANONIQUE, MOT POUR MOT : `src/text_norm.norm_doi`, deja posee dans le noeud de
  // deduplication, dans celui de chainage et dans « Generate NBIB ». Ce noeud-ci ne retirait
  // que le prefixe d'adresse `https://doi.org/`, et rendait donc `doi:doi:10.1000/x` sur une
  // notice portant le prefixe textuel, ou `doi:http://dx.doi.org/...` sur l'adresse en clair.
  //
  // TROIS RETRAITS BORNES, PAS UNE BOUCLE : le texte, puis l'adresse, puis le texte a nouveau.
  // Les deux ordres composes existent, et un ordre fixe en laissait toujours un passer. Le
  // rognage vient EN PREMIER : sans lui, un espace de tete empeche le retrait de l'adresse.
  //
  // ELLE EST NOMMEE EXPRES. `tests/test_identifiant_une_seule_regle.py` DECOUVRE les regles
  // d'identifiant des noeuds par leur signature de code et les EXECUTE contre la regle
  // canonique : ecrite en ligne, celle-ci resterait invisible d'elle, verte a tort.
  //
  // EFFET DE BORD ASSUME, MESURE ET DECIDE PAR L'AUTEUR le 2026-09-07 : sur les 120 542
  // identifiants des corpus consolides du poste (70 149 distincts), 450 changent de valeur,
  // soit 0,6 %, et TOUS par la casse seule. La resolution d'un identifiant y est insensible
  // et la deduplication compare deja en minuscules ; ce qui change est la valeur ecrite dans
  // les fichiers de references, et l'identifiant de ces 450 notices, donc leurs points dans le
  // magasin vectoriel, UNE FOIS, a la transition.
  return String(v || '').trim().toLowerCase()
    .replace(/^doi\s*:\s*/, '')
    .replace(/^https?:\/\/(dx\.)?doi\.org\//, '')
    .replace(/^doi\s*:\s*/, '')
    .trim();
}

// UN CHAMP DE NOTICE RENDU EN TEXTE ROGNE (2026-09-22, revu le 2026-09-23).
//   - Un `id` NUMERIQUE levait « originalId.startsWith is not a function » et le noeud ne
//     rendait AUCUNE notice du lot (notice fabriquee, mesure du 2026-09-22). Aucun noeud de
//     recherche du depot ne pose d'identifiant numerique (lecture du 2026-09-23 : OpenAlex
//     pose une adresse, Crossref `doi:`, PubMed `pmid:`, les autres rien) : c'est une
//     robustesse, pas la reparation d'un chemin de production observe.
//   - Une adresse bordee d'espaces partait telle quelle : le fichier RIS complet de ce
//     workflow (« Save Complete RIS ») ecrivait « UR  -   https://u.org/1  » (mesure du
//     2026-09-23). Les exports NBIB et BibTeX rognent deja leurs valeurs.
// Recompte du 2026-09-23 : deux notices dont chaque champ d'entree est borde de deux espaces,
// une avec DOI et une sans, jouees sur CE noeud avant correction ; dix-neuf noms sortaient
// bordes : id, url, year, journal, pmid, issn, registry_id, publication_type, output_folder,
// question, criteria, search_query, pubmed_query, openalex_query, crossref_query, source,
// _source, et les elements de authors et de publication_types. Zero apres parmi ces dix-neuf.
// `title`, `abstract` et `doi` etaient deja rognes. Borne : les champs de TEXTE que ce noeud
// rend. Les trois reglages `prefilter_enabled`, `prefilter_count` et `max_results` passent tels
// quels, et sortent bordes s'ils arrivent bordes (sonde du 2026-09-28, refutation du tour 2).
// UN CHAMP DE TEXTE QUI N'EST NI UN TEXTE NI UN NOMBRE N'EST PAS UNE VALEUR (2026-09-28, reprise
// du tour 3 du lot). Rendu en texte, un objet, ou une liste qui en porte un, sortait
// « [object Object] », et un DOI objet faisait l'identifiant « doi:[object object] », le meme pour
// toutes ces notices. Balayage du 2026-09-28 : chaque champ que ce code lit sur la notice (38,
// releves dans le code), sous 17 formes (plus des formes imbriquees pour les champs lus en
// profondeur) et 3 provenances, un champ inattendu a la fois, a cote d'une notice saine, soit 2061
// combinaisons : 242 sortaient ce texte avant ce correctif (23 champs), 53 sur HEAD e912d7b, 0
// apres. Un nombre reste un texte (l'identifiant numerique ci-dessus). Aucun noeud de recherche ne
// construit d'objet ni de liste pour les champs que ce noeud lit en texte (lecture du 2026-09-28
// de ultralab-search-apis.json : `authors` et `publication_types` sont des listes, lues a part ;
// plusieurs noeuds recopient la valeur que l'API rend, dont le type ne se lit pas dans le code) :
// c'est une robustesse. L'annee, le DOI et les parties du nom d'auteur de Crossref sont lus plus
// bas par cette regle.
function __ulTexte(v) {
  return (typeof v === 'string' || typeof v === 'number') ? String(v).trim() : '';
}

// CE QUI IDENTIFIE LA NOTICE QUAND ELLE N'A NI DOI NI IDENTIFIANT DE SOURCE : son pmid, sinon
// son identifiant de registre. Banc de collisions de `tests/test_identite_des_notices_sans_doi.py`
// (mesure du 2026-09-23) : sans cette echelle, deux notices de meme titre et de pmid (ou de
// registre) differents recevaient le MEME identifiant, et une notice de Semantic Scholar
// portant le pmid 5 n'avait pas celui de la notice PubMed `pmid:5`. Le prefixe `pmid:` est
// celui que le noeud PubMed ecrit deja : les deux formes se rejoignent.
function __ulIdSecondaire(d) {
  var p = __ulTexte(d.pmid);
  if (p) return 'pmid:' + p;
  var r = __ulTexte(d.registry_id);
  if (r) return 'registry:' + r;
  return '';
}

// LA CLEF DE TITRE (2026-09-23). Dans l'ordre : casse repliee en entier (majuscules puis
// minuscules, pour que « STRASSE » et « Straße » se rejoignent), forme NFKD (la lettre separee
// de son accent, formes de compatibilite ramenees, dont la pleine chasse : piege F16 ; la ligature
// U+FB01 est deja repliee par la casse, sonde du 2026-09-28), retrait des accents
// de la plage U+0300 a U+036F, des points et signes de cantillation hebreux (U+0591 a U+05C7),
// du tatwil arabe (U+0640), des voyelles breves arabes (U+064B a U+065F) et de l'alif suscrit
// (U+0670), puis retrait de tout ce qui n'est ni lettre, ni marque, ni chiffre.
// LES POINTS HEBREUX ET LE TATWIL (2026-09-28, refutation du tour 2) : le meme titre hebreu avec
// et sans points, et le meme titre arabe avec et sans tatwil, recevaient deux clefs (pieges F14
// et F15). Les points sont facultatifs a l'ecrit, comme les voyelles breves arabes ; le tatwil
// est un trait d'allongement, classe lettre par Unicode (Lm), que le filtre final gardait. La
// plage U+0591 a U+05C7 ne contient aucune lettre (55 points de code, categories relevees le
// 2026-09-28 : 51 marques, et 4 ponctuations que le filtre final retirait deja) ; D12 garde deux
// titres hebreux differents distincts.
// L'ALIF SUSCRIT (2026-09-28, refutation du tour 1, piege X4) : retire au tour 1 faute de cas,
// il laissait deux clefs a deux graphies du meme titre arabe, que HEAD fondait (sa classe
// retirait toutes les marques). Il est remis, et le banc porte le piege (F13).
// LES AUTRES MARQUES SONT GARDEES. En devanagari, les signes de voyelle sont des marques
// Unicode : le filtre precedent, `[^\p{L}\p{N}]`, les effacait, et deux titres hindis qui ne
// different que par une voyelle recevaient la meme clef (banc du 2026-09-23, piege D10).
// Les lettres de toutes les ecritures restent : la forme `[^a-z0-9]` effacait les titres non
// latins (mesure conservee du 2026-09-08 : 731 notices sans DOI d'un corpus multi-bases reel,
// 8 titres reduits a rien, 10 identifiants partages).
function __ulCleTitre(t) {
  return String(t)
    .toUpperCase().toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f\u0591-\u05c7\u0640\u064b-\u065f\u0670]/g, '')
    .replace(/[^\p{L}\p{M}\p{N}]+/gu, '');
}

const items = $input.all();

// LES FICHES D'ECART NE SONT PLUS JETEES SANS UN MOT (2026-09-11). Chaque base emet une fiche
// `_diag` : total annonce, total rapporte, motif de l'ecart. Ce noeud les faisait tomber avec
// les notices sans titre, et sur ce chemin un plafond qui coupe 1 434 notices sur 1 834 se
// lisait comme une recherche complete (mesure : 4 entrees, 1 sortie, une seule trace dans le
// journal). Elles restent HORS du corpus, ce ne sont pas des notices : elles iraient sinon aux
// plongements et au dedoublonnage. Elles sont DEPOSEES dans le dossier de la revue, ou
// « Build Export » (ultralab-export.json) les lit pour ecrire la reconciliation de methods.json.
// Recopiees TELLES QUELLES : « Build Export » les lit et les normalise, une seule regle.
const __fichesEcart = items.filter(it => it.json && it.json._diag).map(it => ({
  _source: it.json._source, annonce: it.json.annonce, recupere: it.json.recupere,
  motif: it.json.motif
}));
const __erreurs = items.filter(it => it.json && !it.json._diag && it.json.error)
  .map(it => (it.json._source || '?') + ' : ' + it.json.error);

const normalized = items.map((item, index) => {
  const d = item.json;
  if (d.error || d._empty) return null;

  // LA PROVENANCE EST ROGNEE COMME LES AUTRES TEXTES. Bordee, elle partait telle quelle dans
  // `source` et `_source` (recompte du 2026-09-23 ci-dessus) : l'export NBIB ecrit alors
  // « SO  - [source:  base  ] », et le regroupement par provenance du noeud de deduplication
  // (`String(item._source || item.source || 'unknown').toLowerCase()`) ne rogne pas. Les
  // noeuds de recherche posent des provenances litterales, jamais bordees (lecture du
  // 2026-09-23) : c'est une robustesse.
  const src = __ulTexte(d._source) || __ulTexte(d.source) || 'unknown';
  const originalId = __ulTexte(d.id);

  // Use pre-extracted fields from search-apis (already normalized)
  // LE TITRE EST LU EN TEXTE (2026-09-28, refutation du tour 2). Un titre qui n'etait pas un
  // texte faisait lever « title.trim is not a function », et le noeud ne rendait AUCUNE notice
  // du lot : sonde du 2026-09-28, un titre 1984 ou un titre en tableau a cote d'une notice saine,
  // zero sortie sur HEAD e912d7b comme au tour 2. C'est la classe de defaut de l'identifiant
  // numerique. Les noeuds de recherche recopient le titre que l'API rend (`p.title || ''`, relu
  // le 2026-09-28 dans ultralab-search-apis.json) : son type est celui de l'API. Un tableau (forme
  // brute de Crossref) donne son premier element, comme le repli Crossref le faisait ; un nombre
  // donne son texte ; toute autre valeur n'est pas un titre (rendu en texte, un objet donnait le
  // titre « [object Object] », sonde du 2026-09-28) ; `display_name` (forme brute d'OpenAlex)
  // est lu de la meme facon. Les deux replis propres a OpenAlex et a Crossref, plus bas, sont
  // retires : cette lecture les couvre, et ils reposaient un tableau quand le texte lu etait
  // vide (sonde : `display_name: []` faisait de nouveau lever le noeud). Un titre blanc laisse
  // desormais la place a `display_name` (HEAD e912d7b ecartait alors la notice). Le tri des types
  // est celui de `__ulTexte` : la copie qu'en faisait cette lecture est retiree a la reprise du
  // 2026-09-28, sa mutation survivant au banc depuis que `__ulTexte` trie lui-meme.
  const __ulTitre = function (v) {
    return __ulTexte(Array.isArray(v) ? v[0] : v);
  };
  let title = __ulTitre(d.title) || __ulTitre(d.display_name);
  let abstract = d.abstract || '';
  let authors = Array.isArray(d.authors) ? d.authors : [];
  let year = d.year ? __ulTexte(d.year) : '';
  let journal = d.journal || '';
  let doi = d.doi ? __ulTexte(d.doi) : '';

  // Fallback: try source-specific raw fields ONLY if pre-extracted are empty
  // UNE LISTE BRUTE D'AUTEURS QUI N'EST PAS UNE LISTE NE FAIT PLUS PERDRE LE LOT (2026-09-28).
  // `authorships` d'OpenAlex et `author` de Crossref levaient quand la valeur n'etait pas une
  // liste ou portait un element nul, et le noeud ne rendait alors aucune notice du lot. Balayage
  // du 2026-09-28 decrit a `__ulTexte` : le noeud levait sur 124 combinaisons sur HEAD e912d7b
  // (champs abstract, author, authorships, id, title), sur 52 au tour 2 du lot (author,
  // authorships, title), sur 0 apres.
  if (src === 'openalex') {
    if (authors.length === 0 && Array.isArray(d.authorships)) {
      authors = d.authorships.map(a => (a && a.author && a.author.display_name) || '').filter(Boolean);
    }
    if (!year && d.publication_year) year = __ulTexte(d.publication_year);
    if (!journal && d.primary_location && d.primary_location.source) {
      journal = d.primary_location.source.display_name || '';
    }
    if (!abstract && d.abstract_inverted_index && typeof d.abstract_inverted_index === 'object') {
      const words = {};
      Object.keys(d.abstract_inverted_index).forEach(word => {
        const positions = d.abstract_inverted_index[word];
        if (Array.isArray(positions)) positions.forEach(pos => { words[pos] = word; });
      });
      abstract = Object.keys(words).sort((a, b) => Number(a) - Number(b)).map(k => words[k]).join(' ');
    }
  } else if (src === 'crossref') {
    if (authors.length === 0 && Array.isArray(d.author)) {
      authors = d.author.map(a => a ? (__ulTexte(a.given) + ' ' + __ulTexte(a.family)).trim() : '').filter(Boolean);
    }
    if (!year && d.published && d.published['date-parts'] && d.published['date-parts'][0]) {
      year = __ulTexte(d.published['date-parts'][0][0] || '');
    }
    if (!journal && d['container-title']) {
      journal = Array.isArray(d['container-title']) ? d['container-title'][0] : (d['container-title'] || '');
    }
    if (!doi && d.DOI) doi = __ulTexte(d.DOI);
  }

  // L'identifiant passe par la regle canonique, comme partout ailleurs.
  doi = __ulNormDoi(doi);

  // Construct article URL
  let url = '';
  if (doi) {
    url = 'https://doi.org/' + doi;
  } else if (__ulTexte(d.url)) {
    // L'ADRESSE PROPRE DE LA NOTICE, ET ELLE ETAIT EFFACEE. Les enregistrements d'essai
    // clinique et les prepublications n'ont pas de DOI : leur seule adresse est celle de leur
    // registre, et ce noeud la jetait. Mesure sur 20 notices de registre reelles : 0/20
    // adresses conservees, 20/20 apres.
    url = __ulTexte(d.url);
  } else {
    // L'ADRESSE DEDUITE DE L'IDENTIFIANT. Mesure du 2026-09-22 sur ce noeud : un identifiant
    // `http://x.org/r/1` rendait une adresse vide (la condition exigeait `https://`), `PMID:77`
    // aussi (elle exigeait des minuscules), et un pmid seul sans `id` aussi. Une adresse vide se
    // lit en aval : le fichier RIS complet de ce workflow n'ecrivait aucune ligne `UR` pour ces
    // notices (mesure du 2026-09-23 sur « Save Complete RIS »), et les exports NBIB et BibTeX
    // n'ecrivent la leur que si l'adresse est renseignee.
    const __ref = originalId || __ulIdSecondaire(d);
    const __pmid = __ref.toLowerCase().match(/^pmid\s*:\s*(\d+)$/);
    if (/^https?:\/\//i.test(__ref)) url = __ref;
    else if (__pmid) url = 'https://pubmed.ncbi.nlm.nih.gov/' + __pmid[1];
  }

  // UN IDENTIFIANT QUI NE DEPEND PLUS DU RANG. `src + ':' + index` change des que l'ordre du
  // lot change : mesure sur le corpus reel de 3 804 references, 186 notices sans DOI, et
  // 186/186 de leurs identifiants changent quand une notice arrive en tete. Cinquante points
  // du magasin vectoriel etaient alors ecrases par une AUTRE notice.
  const cleTitre = __ulCleTitre(title);

  if (!title || !title.trim()) return null;

  // ON AJOUTE CE QUI MANQUAIT, ON NE RECOPIE PAS TOUT. Recopier la notice d'entree en entier
  // ferait aussi traverser les champs d'un run PRECEDENT : mesure sur 400 references reelles
  // d'un fichier deja trie et reimporte, 400 decisions de tri traversaient, et l'export les
  // republiait comme celles de ce run (included=196, excluded=160, maybe=44 au lieu de zero).
  // Ces nombres alimentent le tableau et le diagramme de flux.
  //
  // La liste est donc NOMMEE, et chaque nom y est pour une raison mesuree : l'adresse et
  // l'identifiant de registre des notices de litterature grise, le type de publication, les
  // identifiants secondaires, la provenance, et les deux reglages que les noeuds aval lisent.
  //
  // LE ROGNAGE VIENT AVANT LE TEST DE VACUITE, et l'ordre inverse posait une clef vide :
  // mesure du 2026-09-22, une notice dont `registry_id` vaut deux espaces recevait la clef
  // avec ses deux espaces, et une clef presente et vide voyage ensuite comme une valeur.
  // Les deux reglages transportes ne sont pas des textes : ils passent tels quels.
  const __enPlus = {};
  ['registry_id', 'publication_type', 'pmid', 'issn', 'url'].forEach(function (k) {
    const v = __ulTexte(d[k]);
    if (v) __enPlus[k] = v;
  });
  if (Array.isArray(d.publication_types)) {
    const __pt = d.publication_types.map(__ulTexte).filter(Boolean);
    if (__pt.length) __enPlus.publication_types = __pt;
  } else if (__ulTexte(d.publication_types)) {
    __enPlus.publication_types = __ulTexte(d.publication_types);
  }
  ['_pacing_ms', '_ai_settings'].forEach(function (k) {
    if (d[k] !== undefined && d[k] !== null && d[k] !== '') __enPlus[k] = d[k];
  });

  return {
    json: Object.assign({}, __enPlus, {
      // LA REGLE D'IDENTITE DES NOTICES SANS DOI (decision de l'auteur du 2026-09-22) : DOI,
      // sinon identifiant de la source, sinon pmid ou registre, sinon titre replie et ANNEE,
      // SANS la source. Banc de collisions du 2026-09-28 (tests/test_identite_des_notices_sans_doi.py,
      // 35 pieges, notices portant les champs que chaque noeud de recherche pose) : la regle
      // de HEAD e912d7b fait 5 fusions a tort et 20 separations a tort, celle-ci 2 et 5.
      // Les sept restantes sont nommees dans ce fichier de cas : deux titres generiques de
      // meme annee (« Editorial ») se fondent, deux mots vietnamiens qui ne different que par
      // le ton aussi ; « & » contre « and », des balises de mise en forme, le meme article vu
      // par une base qui donne le pmid et par une autre qui ne le donne pas (deux pieges), et
      // l'annee en ligne contre l'annee du numero restent separes.
      // LECTEUR DE L'IDENTIFIANT EN AVAL, mesure le 2026-09-23 : le seul est le magasin
      // vectoriel (`ultralab-qdrant-store.json`, point `hashCode(article.id || ...)`), ecrit
      // AVANT le dedoublonnage ; le dedoublonnage ne le lit pas (DOI, puis titre, annee et
      // premier auteur, puis titre seul d'au moins 20 caracteres).
      id: doi ? 'doi:' + doi
              : (originalId || __ulIdSecondaire(d)
                 || (cleTitre ? ('ti:' + cleTitre + ':' + year)
                              : ('rang' + index))),
      // `title` ET `year` SORTENT TELS QU'ILS ONT ETE LUS (2026-09-29, role banc du tour 3) : ils
      // ne recoivent de valeur que par `__ulTexte` ou '' (lecture du code : une affectation de
      // `title`, trois de `year`). Leur rognage de sortie, celui de l'annee dans l'identifiant, et
      // les gardes `t == null` de `__ulCleTitre` et `d &&` de `__ulIdSecondaire` (appelee apres
      // `d.error`, qui leve deja sur une notice nulle) ne changeaient aucune sortie : 0 lot sur
      // 6221 (balayage du fichier de cas du rognage, pieges et cas bordes du fichier de cas de
      // l'identite) ; leurs mutations survivaient au banc.
      title,
      abstract: __ulTexte(abstract),
      // Un nom d'auteur vide n'est pas un auteur : garde, il ecrirait une ligne `AU  - ` sans
      // nom dans le fichier RIS complet de ce workflow (« Save Complete RIS »).
      // SEULS LES NOMS EN TEXTE SONT ROGNES (2026-09-28, refutation du tour 2) : rendu en texte,
      // un auteur objet (`{name: ...}`) sortait « [object Object] ». Il sort tel qu'il est
      // arrive, comme sur HEAD e912d7b ; un element nul n'est pas un auteur (sonde du 2026-09-28).
      authors: authors.map(function (a) { return typeof a === 'string' ? a.trim() : a; })
        .filter(function (a) { return a != null && a !== ''; }),
      year,
      journal: __ulTexte(journal),
      doi,
      url,
      source: src,
      // LE CHAMP DE PROVENANCE, REPOSE (2026-09-22). Il n'etait pas rendu pour les notices
      // dont le noeud de recherche pose `source` sans `_source` (releve du 2026-09-23 dans
      // ultralab-search-apis.json : BASE, DOAJ, Lens, ScienceDirect, Semantic Scholar), ni pour
      // le repli « unknown ». SON LECTEUR EN AVAL, sur le chemin de ce noeud : « Build Export »
      // (ultralab-export.json, appele par le meme orchestrateur). Il le lisait sans repli sur
      // `source` jusqu'au 2026-10-16, et son absence coutait alors la ligne « SO » de l'export
      // NBIB (mesure du 2026-09-23 sur « Build Export »). Depuis (PROVENANCE_UNE_REGLE_v1,
      // fonction `__ulProvenance`), il lit `_source` d'abord, avec repli sur `source` : ce
      // champ n'est plus indispensable a la ligne « SO ». (Commentaire corrige le 2026-10-19,
      // lot « references », P51 : il affirmait encore la lecture sans repli.)
      _source: src,
      question: __ulTexte(d.question),
      criteria: __ulTexte(d.criteria),
      search_query: __ulTexte(d.search_query),
      pubmed_query: __ulTexte(d.pubmed_query),
      openalex_query: __ulTexte(d.openalex_query),
      crossref_query: __ulTexte(d.crossref_query),
      output_folder: __ulTexte(d.output_folder),
      prefilter_enabled: d.prefilter_enabled,
      prefilter_count: d.prefilter_count,
      max_results: d.max_results
    })
  };
}).filter(item => item !== null);

// LE DEPOT SE FAIT A CHAQUE RUN, MEME VIDE. Le dossier de la revue porte le nom de la question,
// pas celui du run : deux runs sur la meme question y ecrivent, et une declaration qui ne serait
// pas remplacee serait relue par l'export du run suivant. Le dossier est celui que « Build
// Export » lira, par la meme expression (premiere notice, sinon /desktop).
(function __ulDeposerEcarts() {
  if (!normalized.length) {
    if (__fichesEcart.length) console.log('[ecarts] aucune notice, dossier de la revue inconnu : '
      + __fichesEcart.length + ' fiche(s) non deposee(s)');
    return;
  }
  const dossier = normalized[0].json.output_folder || '/desktop';
