// MESURE DU 2026-09-04 sur un run reel de 3 804 references : le .ris livre plafonnait a
// EXACTEMENT 2 000 caracteres, 867 notices assises pile sur la borne, quand le .nbib du
// MEME run, ecrit par le MEME noeud, montait a 18 690. La coupe ne venait donc pas de la
// source. Cout : 22,6 % des resumes ampute, environ 417 000 caracteres perdus, et rien ne
// distinguait un resume court d'un resume coupe. Ni RIS ni BibTeX n'imposent de limite.
// PROVENANCE_NEUTRE_v1 (2026-10-20, P47) : la provenance d'un import se lit sous son LIBELLE, dans la
// langue du document. L'import range un identifiant neutre (« reference-library »,
// « screening-platform-import ») ; les valeurs rangees avant ce jour et les libelles relus d'un fichier
// se lisent pareil, si bien qu'un corpus qui les mele ne donne qu'une ligne. Toute autre provenance
// (une base interrogee) reste telle quelle. COPIE A L'IDENTIQUE de src/provenance_neutre.py (`libelle`)
// et de app/src/lib/sourceReference.ts : si l'une change, changer les autres (cas qui les executent
// toutes : tests/test_provenance_neutre_du_20_10.py).
function __ulProvenanceLisible(s, lang) {
  const libelles = {
    'reference-library': ['Bibliothèque de références', 'Reference library'],
    'screening-platform-import': ['Plateforme de tri (import)', 'Screening platform (import)']
  };
  const anciennes = { 'zotero': 'reference-library', 'rayyan-import': 'screening-platform-import',
    'covidence-import': 'screening-platform-import' };
  const a = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
  if (typeof s !== 'string') return s == null ? '' : s;
  const k = s.normalize('NFC').trim().toLowerCase();
  let id = a(libelles, k) ? k : (a(anciennes, k) ? anciennes[k] : null);
  if (!id) {
    for (const i of Object.keys(libelles)) {
      if (libelles[i][0].toLowerCase() === k || libelles[i][1].toLowerCase() === k) id = i;
    }
  }
  if (!id) return s;
  return libelles[id][String(lang || '').toLowerCase().indexOf('en') === 0 ? 1 : 0];
}
